'use strict';

/**
* LAPACK routine to return a vector of `N` random real numbers drawn from a uniform (0,1) distribution.
*
* @module @stdlib/lapack-base-dlaruv
*
* @example
* import Int32Array from '@stdlib/array-int32';
* import Float64Array from '@stdlib/array-float64';
* import dlaruv from '@stdlib/lapack-base-dlaruv';
*
* var seed = new Int32Array( [ 0, 1, 2, 3 ] );
* var x = new Float64Array( 3 );
*
* dlaruv( seed, 3, x );
* // x => <Float64Array>[ ~0.1319, ~0.2338, ~0.3216 ]
*
* @example
* import Int32Array from '@stdlib/array-int32';
* import Float64Array from '@stdlib/array-float64';
* import dlaruv from '@stdlib/lapack-base-dlaruv';
*
* var seed = new Int32Array( [ 0, 1, 2, 3 ] );
* var x = new Float64Array( 3 );
*
* dlaruv.ndarray( 3, seed, 1, 0, x, 1, 0 );
* // x => <Float64Array>[ ~0.1319, ~0.2338, ~0.3216 ]
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils-try-require';
import isError from '@stdlib/assert-is-error';
import main from './main.js';


// MAIN //

var dlaruv;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dlaruv = main;
} else {
	dlaruv = tmp;
}


// EXPORTS //

export default dlaruv;

